#define HASH_CR_MODE_MASK            0x00000040U                     ///< Mask for HASH_CR_MODE
#define HASH_CR_ALGO_MASK            0x00000080U                     ///< Mask for HASH_CR_ALGO
#define HASH_CR_NBW_MASK             0x00000F00U                     ///< Mask for HASH_CR_NBW
#define HASH_CR_DINNE_MASK           0x00001000U                     ///< Mask for HASH_CR_DINNE
#define HASH_CR_LKEY_MASK            0x00010000U                     ///< Mask for HASH_CR_LKEY

/*  Definitions of Bit-Positions  */
#define HASH_CR_INIT_POS             0x02U                           ///< Position for HASH_CR_INIT
#define HASH_CR_DMAE_POS             0x03U                           ///< Position for HASH_CR_DMAE
#define HASH_CR_DATATYPE_POS         0x04U                           ///< Position for HASH_CR_DATATYPE
