#define HASH_CR_DINNE_POS            0x0CU                           ///< Position for HASH_CR_DINNE
#define HASH_CR_LKEY_POS             0x10U                           ///< Position for HASH_CR_LKEY

/*  Definitions for accessing register HASH_CR and its flags  */
#define HASH_CR                      (__HASH_CR.tReg)                   ///< control register
#define HASH_CR_INIT                 (__HASH_CR.tBits.bfInit)           ///< Initialize message digest calculation
#define HASH_CR_DMAE                 (__HASH_CR.tBits.bfDmae)           ///< DMA enable
#define HASH_CR_DATATYPE             (__HASH_CR.tBits.bfDatatype)       ///< Data type selection
#define HASH_CR_MODE                 (__HASH_CR.tBits.bfMode)           ///< Mode selection
#define HASH_CR_ALGO                 (__HASH_CR.tBits.bfAlgo)           ///< Algorithm selection
#define HASH_CR_NBW                  (__HASH_CR.tBits.bfNbw)      ///< Number of words already pushed
#define HASH_CR_DINNE                (__HASH_CR.tBits.bfDinne)    ///< DIN not empty
#define HASH_CR_LKEY                 (__HASH_CR.tBits.bfLkey)           ///< Long key selection

/** Type definition: CR, control register */
